    18→        note.title || note.data?.title || note.values?.title || 'Untitled';
    19→      const content =
    20→        note.content ||
    21→        note.data?.content ||
    22→        note.values?.content ||
    23→        note.text ||
    24→        note.body;
    25→      const timestamp =
    26→        note.timestamp ||
    27→        note.created_at ||
    28→        note.data?.created_at ||
    29→        note.values?.created_at ||
    30→        'unknown';
    31→
    32→      return `- ${title} (Created: ${timestamp})\n  ${
    33→        content
    34→          ? content.length > 200
    35→            ? content.substring(0, 200) + '...'
    36→            : content
