     1→/**
     2→ * Notes-related tool configurations for companies
     3→ */
     4→import {
     5→  getCompanyNotes,
     6→  createCompanyNote,
     7→} from '../../../objects/companies/index.js';
     8→import { NotesToolConfig, CreateNoteToolConfig } from '../../tool-types.js';
     9→
    10→// Company notes tool configurations
    11→export const notesToolConfigs = {
    12→  notes: {
    13→    name: 'get-company-notes',
    14→    handler: getCompanyNotes,
    15→    formatResult: (notes: any) => {
    16→      if (!notes || notes.length === 0) {
    17→        return 'No notes found for this company.';
    18→      }
    19→
    20→      // Debug logging in development to help identify API response structure
    21→      if (process.env.NODE_ENV === 'development' || process.env.DEBUG) {
    22→        console.log(
    23→          '[get-company-notes] Debug - Raw notes response:',
    24→          JSON.stringify(notes.slice(0, 1), null, 2)
    25→        );
    26→      }
    27→
    28→      return `Found ${notes.length} notes:\n${notes
    29→        .map((note: any) => {
    30→          // The AttioNote interface shows these are direct properties
    31→          // Check multiple possible field structures from the API (Issue #365)
