    },
  },
  {
    name: 'get-company-business-info',
    description: 'Get business information about a company',
    inputSchema: {
      type: 'object',
      properties: {
        companyId: {
          type: 'string',
          description: 'ID of the company',
        },
      },
      required: ['companyId'],
