     1→/**
     2→ * Error class hierarchy for Attio API errors
     3→ * Includes specialized error types for API interactions and validation
     4→ */
     5→
     6→/**
     7→ * Base class for all Attio API errors
     8→ */
     9→export class AttioApiError extends Error {
    10→  /**
    11→   * Create an AttioApiError
    12→   *
    13→   * @param message - Error message
    14→   * @param statusCode - HTTP status code
    15→   * @param endpoint - API endpoint that was called
    16→   * @param details - Additional error details
    17→   */
    18→  constructor(
    19→    message: string,
    20→    public readonly statusCode: number,
    21→    public readonly endpoint: string,
    22→    public readonly method: string,
    23→    public readonly details?: any
    24→  ) {
    25→    super(message);
    26→    this.name = 'AttioApiError';
    27→
    28→    // This line is needed to properly capture the stack trace in derived classes
    29→    Object.setPrototypeOf(this, AttioApiError.prototype);
    30→  }
    31→
    32→  /**
    33→   * Get a formatted representation of the error for logging
    34→   */
    35→  toFormattedString(): string {
    36→    return (
    37→      `${this.name} (${this.statusCode}): ${this.message}\n` +
    38→      `Endpoint: ${this.method} ${this.endpoint}\n` +
    39→      `Details: ${JSON.stringify(this.details || {}, null, 2)}`
    40→    );
    41→  }
    42→}
    43→
    44→/**
    45→ * Error for authentication issues (401)
    46→ */
    47→export class AuthenticationError extends AttioApiError {
    48→  constructor(
    49→    message: string = 'Authentication failed. Please check your API key.',
    50→    endpoint: string,
    51→    method: string,
    52→    details?: any
    53→  ) {
    54→    super(message, 401, endpoint, method, details);
    55→    this.name = 'AuthenticationError';
    56→
    57→    // This line is needed to properly capture the stack trace
    58→    Object.setPrototypeOf(this, AuthenticationError.prototype);
    59→  }
    60→}
    61→
    62→/**
    63→ * Error for authorization issues (403)
    64→ */
    65→export class AuthorizationError extends AttioApiError {
    66→  constructor(
    67→    message: string = 'Authorization failed. Your API key lacks the necessary permissions.',
    68→    endpoint: string,
    69→    method: string,
    70→    details?: any
    71→  ) {
    72→    super(message, 403, endpoint, method, details);
    73→    this.name = 'AuthorizationError';
    74→
    75→    // This line is needed to properly capture the stack trace
    76→    Object.setPrototypeOf(this, AuthorizationError.prototype);
    77→  }
    78→}
    79→
    80→/**
    81→ * Error for resource not found issues (404)
    82→ */
    83→export class ResourceNotFoundError extends AttioApiError {
    84→  constructor(
    85→    resourceType: string,
    86→    resourceId: string,
    87→    endpoint: string,
    88→    method: string,
    89→    details?: any
    90→  ) {
    91→    super(
    92→      `${resourceType} with ID '${resourceId}' not found`,
    93→      404,
    94→      endpoint,
    95→      method,
    96→      details
    97→    );
    98→    this.name = 'ResourceNotFoundError';
    99→
   100→    // This line is needed to properly capture the stack trace
   101→    Object.setPrototypeOf(this, ResourceNotFoundError.prototype);
   102→  }
   103→}
   104→
   105→/**
   106→ * Error for invalid request issues (400)
   107→ */
   108→export class InvalidRequestError extends AttioApiError {
   109→  constructor(
   110→    message: string,
   111→    endpoint: string,
   112→    method: string,
   113→    details?: any
   114→  ) {
   115→    super(message, 400, endpoint, method, details);
   116→    this.name = 'InvalidRequestError';
   117→
   118→    // This line is needed to properly capture the stack trace
   119→    Object.setPrototypeOf(this, InvalidRequestError.prototype);
   120→  }
   121→}
   122→
   123→/**
   124→ * Error for rate limit issues (429)
   125→ */
   126→export class RateLimitError extends AttioApiError {
   127→  constructor(
   128→    message: string = 'Rate limit exceeded. Please try again later.',
   129→    endpoint: string,
   130→    method: string,
   131→    details?: any
   132→  ) {
   133→    super(message, 429, endpoint, method, details);
   134→    this.name = 'RateLimitError';
   135→
   136→    // This line is needed to properly capture the stack trace
   137→    Object.setPrototypeOf(this, RateLimitError.prototype);
   138→  }
   139→}
   140→
   141→/**
   142→ * Error for server-side issues (500, 502, 503, 504)
   143→ */
   144→export class ServerError extends AttioApiError {
   145→  constructor(
   146→    statusCode: number,
   147→    message: string = 'Server error occurred',
   148→    endpoint: string,
   149→    method: string,
   150→    details?: any
   151→  ) {
   152→    super(
   153→      `Server error (${statusCode}): ${message}`,
   154→      statusCode,
   155→      endpoint,
   156→      method,
   157→      details
   158→    );
   159→    this.name = 'ServerError';
   160→
   161→    // This line is needed to properly capture the stack trace
   162→    Object.setPrototypeOf(this, ServerError.prototype);
   163→  }
   164→}
   165→
   166→/**
   167→ * Factory function to create the appropriate error type based on status code
   168→ *
   169→ * @param statusCode - HTTP status code
   170→ * @param message - Error message
   171→ * @param endpoint - API endpoint that was called
   172→ * @param method - HTTP method used
   173→ * @param details - Additional error details
   174→ * @returns The appropriate error instance
   175→ */
   176→export function createApiErrorFromStatus(
   177→  statusCode: number,
   178→  message: string,
   179→  endpoint: string,
   180→  method: string,
   181→  details?: any
   182→): AttioApiError {
   183→  switch (statusCode) {
   184→    case 400:
   185→      return new InvalidRequestError(message, endpoint, method, details);
   186→    case 401:
   187→      return new AuthenticationError(message, endpoint, method, details);
   188→    case 403:
   189→      return new AuthorizationError(message, endpoint, method, details);
   190→    case 404:
   191→      // This is a generic case - for specific resources, use ResourceNotFoundError constructor directly
   192→      return new ResourceNotFoundError(
   193→        'Resource',
   194→        'unknown',
   195→        endpoint,
   196→        method,
   197→        details
   198→      );
   199→    case 429:
   200→      return new RateLimitError(message, endpoint, method, details);
   201→    case 500:
   202→    case 502:
   203→    case 503:
   204→    case 504:
   205→      return new ServerError(statusCode, message, endpoint, method, details);
   206→    default:
   207→      return new AttioApiError(message, statusCode, endpoint, method, details);
   208→  }
   209→}
   210→
   211→/**
   212→ * Create an appropriate error from Axios error response
   213→ *
   214→ * @param error - The caught error
   215→ * @param endpoint - API endpoint that was called
   216→ * @param method - HTTP method used
   217→ * @returns The appropriate error instance
   218→ */
   219→export function createApiErrorFromAxiosError(
   220→  error: any,
   221→  endpoint: string,
   222→  method: string
   223→): AttioApiError {
   224→  const statusCode = error.response?.status || 500;
   225→  const message =
   226→    error.response?.data?.message || error.message || 'Unknown API error';
   227→  const details = error.response?.data || {};
   228→
   229→  // Special case for ResourceNotFoundError with object types
   230→  if (statusCode === 404 && endpoint.includes('/objects/')) {
   231→    // Extract resource type and ID from endpoint
   232→    // Assuming endpoint format like /objects/{type}/records/{id}
   233→    const matches = endpoint.match(/\/objects\/([^\/]+)\/records\/([^\/]+)/);
   234→    if (matches && matches.length >= 3) {
   235→      const [, resourceType, resourceId] = matches;
   236→      // Format resource type properly: 'people' -> 'Person', 'companies' -> 'Company'
   237→      let formattedType;
   238→      if (resourceType === 'people') {
   239→        formattedType = 'Person';
   240→      } else if (resourceType === 'companies') {
   241→        formattedType = 'Company';
   242→      } else {
   243→        // Default formatting for other types
   244→        formattedType =
   245→          resourceType.charAt(0).toUpperCase() + resourceType.slice(1, -1);
   246→      }
   247→
   248→      return new ResourceNotFoundError(
   249→        formattedType,
   250→        resourceId,
   251→        endpoint,
   252→        method,
   253→        details
   254→      );
   255→    }
   256→  }
   257→
   258→  return createApiErrorFromStatus(
   259→    statusCode,
   260→    message,
   261→    endpoint,
   262→    method,
   263→    details
   264→  );
   265→}
   266→
   267→/**
   268→ * Filter error categories for more targeted error handling
   269→ */
   270→export enum FilterErrorCategory {
   271→  STRUCTURE = 'structure', // Basic structure issues (missing filters array)
   272→  ATTRIBUTE = 'attribute', // Attribute-related issues
   273→  CONDITION = 'condition', // Condition-related issues
   274→  VALUE = 'value', // Value-related issues
   275→  TRANSFORMATION = 'transformation', // API format transformation issues
   276→}
   277→
   278→/**
   279→ * Error class for filter validation issues
   280→ *
   281→ * Used when validating filter conditions and structures to ensure they meet
   282→ * the requirements of the Attio API format.
   283→ *
   284→ * @example
   285→ * ```typescript
   286→ * try {
   287→ *   // Validate filter conditions
   288→ *   if (!isValidFilterCondition(condition)) {
   289→ *     throw new FilterValidationError(
   290→ *       `Invalid filter condition: ${condition}`,
   291→ *       FilterErrorCategory.CONDITION
   292→ *     );
   293→ *   }
   294→ * } catch (error) {
   295→ *   if (error instanceof FilterValidationError) {
   296→ *     // Handle filter validation error based on category
   297→ *     if (error.category === FilterErrorCategory.CONDITION) {
   298→ *       // Handle condition-specific error
   299→ *     }
   300→ *   }
   301→ * }
   302→ * ```
   303→ */
   304→export class FilterValidationError extends Error {
   305→  /**
   306→   * Create a new FilterValidationError
   307→   *
   308→   * @param message - Detailed error message explaining the validation issue
   309→   * @param category - Error category for targeted handling (default: STRUCTURE)
   310→   */
   311→  constructor(
   312→    message: string,
   313→    public readonly category: FilterErrorCategory = FilterErrorCategory.STRUCTURE
   314→  ) {
   315→    super(message);
   316→    this.name = 'FilterValidationError';
   317→
   318→    // This line is needed to properly capture the stack trace
   319→    Object.setPrototypeOf(this, FilterValidationError.prototype);
   320→  }
   321→}
   322→
   323→/**
   324→ * Error for relationship filter validation issues
   325→ *
   326→ * @example
   327→ * ```typescript
   328→ * try {
   329→ *   if (!isValidRelationshipType(type)) {
   330→ *     throw new RelationshipFilterError(
   331→ *       `Invalid relationship type: ${type}`,
   332→ *       'people',
   333→ *       'companies'
   334→ *     );
   335→ *   }
   336→ * } catch (error) {
   337→ *   if (error instanceof RelationshipFilterError) {
   338→ *     // Handle relationship filter error
   339→ *     console.log(`Relationship error between ${error.sourceType} and ${error.targetType}`);
   340→ *   }
   341→ * }
   342→ * ```
   343→ */
   344→export class RelationshipFilterError extends FilterValidationError {
   345→  /**
   346→   * Create a RelationshipFilterError
   347→   *
   348→   * @param message - Error message
   349→   * @param sourceType - The source entity type (e.g., 'people', 'companies')
   350→   * @param targetType - The target entity type (e.g., 'companies', 'lists')
   351→   * @param relationshipType - The type of relationship that failed validation
   352→   */
   353→  constructor(
   354→    message: string,
   355→    public readonly sourceType?: string,
   356→    public readonly targetType?: string,
   357→    public readonly relationshipType?: string
   358→  ) {
   359→    // Relationships are a special type of filter condition
   360→    super(message, FilterErrorCategory.CONDITION);
   361→    this.name = 'RelationshipFilterError';
   362→
   363→    // This line is needed to properly capture the stack trace in derived classes
   364→    Object.setPrototypeOf(this, RelationshipFilterError.prototype);
   365→  }
   366→}
   367→
   368→/**
   369→ * Error specifically for list relationship issues
   370→ *
   371→ * @example
   372→ * ```typescript
   373→ * try {
   374→ *   if (!isValidListId(listId)) {
   375→ *     throw new ListRelationshipError(`Invalid list ID: ${listId}`, 'people', listId);
   376→ *   }
   377→ * } catch (error) {
   378→ *   if (error instanceof ListRelationshipError) {
   379→ *     // Handle list relationship error
   380→ *   }
   381→ * }
   382→ * ```
   383→ */
   384→export class ListRelationshipError extends RelationshipFilterError {
   385→  /**
   386→   * Create a ListRelationshipError
