   176→/**
   177→ * Universal search handler with performance tracking
   178→ */
   179→export async function handleUniversalSearch(params: UniversalSearchParams): Promise<AttioRecord[]> {
   180→  const { resource_type, query, filters, limit, offset } = params;
   181→  
   182→  // Start performance tracking
   183→  const perfId = enhancedPerformanceTracker.startOperation(
   184→    'search-records',
   185→    'search',
   186→    { 
   187→      resourceType: resource_type, 
   188→      hasQuery: !!query,
   189→      hasFilters: !!(filters && Object.keys(filters).length > 0),
   190→      limit,
   191→      offset 
   192→    }
   193→  );
   194→  
   195→  try {
   196→    // Track validation timing
   197→    const validationStart = performance.now();
   198→    
   199→    // Validate limit parameter to prevent abuse
   200→    if (limit && (limit < 0 || !Number.isInteger(limit))) {
   201→      enhancedPerformanceTracker.endOperation(perfId, false, 'Invalid limit parameter', 400);
   202→      throw new Error('limit must be a positive integer');
   203→    }
   204→    
   205→    if (limit && limit > 100) {
   206→      enhancedPerformanceTracker.endOperation(perfId, false, 'Limit exceeds maximum', 400);
   207→      throw new Error('limit must not exceed 100');
   208→    }
   209→    
   210→    if (offset && (offset < 0 || !Number.isInteger(offset))) {
   211→      enhancedPerformanceTracker.endOperation(perfId, false, 'Invalid offset parameter', 400);
   212→      throw new Error('offset must be a non-negative integer');
   213→    }
   214→    
   215→    enhancedPerformanceTracker.markTiming(perfId, 'validation', performance.now() - validationStart);
   216→    
   217→    // Track API call timing
   218→    const apiStart = enhancedPerformanceTracker.markApiStart(perfId);
   219→    let results: AttioRecord[];
   220→    
   221→    try {
   222→      switch (resource_type) {
   223→        case UniversalResourceType.COMPANIES:
   224→          if (filters && Object.keys(filters).length > 0) {
   225→            results = await advancedSearchCompanies(filters, limit, offset);
   226→          } else {
   227→            results = await searchCompanies(query || '');
   228→          }
   229→          break;
   230→          
   231→        case UniversalResourceType.PEOPLE:
   232→          if (filters && Object.keys(filters).length > 0) {
   233→            const paginatedResult = await advancedSearchPeople(filters, { limit, offset });
   234→            results = paginatedResult.results;
   235→          } else if (!query || query.trim().length === 0) {
   236→            // If no query provided, use listPeople instead of searchPeople
   237→            results = await listPeople(limit || 20);
   238→          } else {
   239→            results = await searchPeople(query);
   240→          }
   241→          break;
   242→          
   243→        case UniversalResourceType.RECORDS:
   244→          results = await listObjectRecords('records', { 
   245→            pageSize: limit, 
   246→            page: Math.floor((offset || 0) / (limit || 10)) + 1 
   247→          });
   248→          break;
   249→          
