   763→/**
   764→ * Enhanced error handling utility for universal operations
   765→ */
   766→export function createUniversalError(operation: string, resourceType: string, originalError: any): Error {
   767→  // If it's already a UniversalValidationError, pass it through
   768→  if (originalError instanceof UniversalValidationError) {
   769→    return originalError;
   770→  }
   771→  
   772→  // Classify the error type based on the original error
   773→  let errorType = ErrorType.SYSTEM_ERROR;
   774→  
   775→  if (originalError?.message?.includes('not found') || 
   776→      originalError?.message?.includes('invalid') ||
   777→      originalError?.message?.includes('required') ||
   778→      originalError?.status === 400) {
   779→    errorType = ErrorType.USER_ERROR;
   780→  } else if (originalError?.status >= 500 || 
   781→             originalError?.message?.includes('network') ||
   782→             originalError?.message?.includes('timeout')) {
   783→    errorType = ErrorType.API_ERROR;
   784→  }
   785→  
   786→  const message = `Universal ${operation} failed for resource type ${resourceType}: ${originalError.message}`;
   787→  
   788→  return new UniversalValidationError(
   789→    message,
   790→    errorType,
   791→    {
   792→      suggestion: getOperationSuggestion(operation, resourceType, originalError),
   793→      cause: originalError
   794→    }
   795→  );
   796→}
   797→
   798→/**
   799→ * Get helpful suggestions based on the operation and error
   800→ */
   801→function getOperationSuggestion(operation: string, resourceType: string, error: any): string | undefined {
   802→  const errorMessage = error?.message?.toLowerCase() || '';
   803→  
   804→  // Deal-specific suggestions
   805→  if (resourceType === 'deals') {
   806→    if (errorMessage.includes('cannot find attribute with slug/id "company_id"')) {
   807→      return 'Use "associated_company" instead of "company_id" for linking deals to companies';
   808→    }
   809→    
   810→    if (errorMessage.includes('cannot find attribute with slug/id "company"')) {
   811→      return 'Use "associated_company" instead of "company" for linking deals to companies';
   812→    }
   813→    
   814→    if (errorMessage.includes('cannot find status')) {
   815→      return 'Invalid deal stage. Check available stages with discover-attributes tool or use the default stage';
   816→    }
   817→    
   818→    if (errorMessage.includes('invalid value was passed to attribute with slug "value"')) {
   819→      return 'Deal value should be a simple number (e.g., 9780). Attio automatically handles currency formatting.';
   820→    }
   821→    
   822→    if (errorMessage.includes('deal_stage')) {
   823→      return 'Use "stage" instead of "deal_stage" for deal status';
   824→    }
   825→    
   826→    if (errorMessage.includes('deal_value')) {
   827→      return 'Use "value" instead of "deal_value" for deal amount';
   828→    }
   829→    
   830→    if (errorMessage.includes('deal_name')) {
   831→      return 'Use "name" instead of "deal_name" for deal title';
   832→    }
   833→    
   834→    if (errorMessage.includes('description')) {
   835→      return 'Deals do not have a "description" field. Available fields: name, stage, value, owner, associated_company, associated_people';
   836→    }
   837→    
   838→    if (errorMessage.includes('expected_close_date') || errorMessage.includes('close_date')) {
   839→      return 'Deals do not have a built-in close date field. Consider using a custom field or tracking this separately';
   840→    }
   841→    
   842→    if (errorMessage.includes('probability') || errorMessage.includes('likelihood')) {
   843→      return 'Deals do not have a built-in probability field. Consider using custom fields or tracking probability in stage names';
   844→    }
   845→    
   846→    if (errorMessage.includes('source') || errorMessage.includes('lead_source')) {
   847→      return 'Deals do not have a built-in source field. Consider using custom fields to track deal sources';
   848→    }
   849→    
   850→    if (errorMessage.includes('currency') && !errorMessage.includes('currency_code')) {
   851→      return 'Currency is set automatically based on workspace settings. Just provide a numeric value for the deal amount';
   852→    }
   853→    
   854→    if (errorMessage.includes('contact') || errorMessage.includes('primary_contact')) {
   855→      return 'Use "associated_people" to link contacts/people to deals';
   856→    }
   857→    
   858→    if (errorMessage.includes('notes') || errorMessage.includes('comments')) {
   859→      return 'Deal notes should be created separately using the notes API after the deal is created';
