    63→// Performance and safety constants
    64→const MAX_BATCH_SIZE = 50; // Maximum number of records per batch operation
    65→const BATCH_DELAY_MS = 100; // Delay between API calls to respect rate limits
    66→const MAX_CONCURRENT_REQUESTS = 5; // Maximum number of concurrent API requests
    67→
    68→/**
    69→ * Validates batch operation size for performance and safety
    70→ */
    71→function validateBatchSize(items: any[], operationType: string): void {
    72→  if (items && items.length > MAX_BATCH_SIZE) {
    73→    throw new Error(
    74→      `Batch ${operationType} size (${items.length}) exceeds maximum allowed (${MAX_BATCH_SIZE}). ` +
    75→      `Please split into smaller batches for performance and safety.`
    76→    );
    77→  }
