    87→/**
    88→ * Processes items in parallel with controlled concurrency and error isolation
    89→ * Each item's success/failure is tracked independently for batch operations
    90→ */
    91→async function processInParallelWithErrorIsolation<T>(
    92→  items: T[],
    93→  processor: (item: T, index: number) => Promise<any>,
    94→  maxConcurrency: number = MAX_CONCURRENT_REQUESTS
    95→): Promise<Array<{ success: boolean; result?: any; error?: string; data?: T }>> {
    96→  const results: Array<{ success: boolean; result?: any; error?: string; data?: T }> = [];
    97→  
    98→  // Process items in chunks to control concurrency
    99→  for (let i = 0; i < items.length; i += maxConcurrency) {
   100→    const chunk = items.slice(i, i + maxConcurrency);
   101→    
   102→    // Process chunk in parallel with Promise.allSettled for error isolation
   103→    const chunkPromises = chunk.map(async (item, chunkIndex) => {
   104→      try {
   105→        const result = await processor(item, i + chunkIndex);
   106→        return { success: true, result };
   107→      } catch (error) {
   108→        return { 
   109→          success: false, 
   110→          error: error instanceof Error ? error.message : String(error), 
   111→          data: item 
   112→        };
   113→      }
   114→    });
   115→    
   116→    const chunkResults = await Promise.allSettled(chunkPromises);
   117→    
   118→    // Add results from this chunk (allSettled results are always fulfilled)
   119→    for (const settledResult of chunkResults) {
   120→      if (settledResult.status === 'fulfilled') {
   121→        results.push(settledResult.value);
   122→      } else {
   123→        // This should rarely happen since we handle errors in the inner promise
   124→        results.push({ 
   125→          success: false, 
   126→          error: `Unexpected processing error: ${settledResult.reason}` 
   127→        });
   128→      }
   129→    }
   130→    
   131→    // Add delay between chunks to respect rate limits
   132→    if (i + maxConcurrency < items.length) {
   133→      await delay(BATCH_DELAY_MS);
   134→    }
   135→  }
   136→  
   137→  return results;
   138→}
