/**
 * Batch operation tool configurations for companies
 */
import {
  batchCreateCompanies,
  batchUpdateCompanies,
  batchDeleteCompanies,
  batchSearchCompanies,
  batchGetCompanyDetails,
} from '../../../objects/batch-companies.js';
import { ToolConfig } from '../../tool-types.js';

// Company batch tool configurations
export const batchToolConfigs = {
  batchCreate: {
    name: 'batch-create-companies',
    handler: batchCreateCompanies,
    formatResult: (result: any) => {
      const { results, summary } = result;
      let output = `Batch Create Summary: ${summary.succeeded}/${summary.total} succeeded\n`;

      results.forEach((item: any) => {
        if (item.success) {
          output += `✓ Created: ${
            item.data.values?.name?.[0]?.value || 'Unknown'
          } (ID: ${item.data.id?.record_id})\n`;
        } else {
          output += `✗ Failed: ${item.error?.message || 'Unknown error'}\n`;
        }
      });

      return output;
    },
  } as ToolConfig,

  batchUpdate: {
    name: 'batch-update-companies',
    handler: batchUpdateCompanies,
    formatResult: (result: any) => {
      const { results, summary } = result;
      let output = `Batch Update Summary: ${summary.succeeded}/${summary.total} succeeded\n`;

      results.forEach((item: any) => {
        if (item.success) {
          output += `✓ Updated: ${
            item.data.values?.name?.[0]?.value || 'Unknown'
          } (ID: ${item.data.id?.record_id})\n`;
        } else {
          output += `✗ Failed: ${item.error?.message || 'Unknown error'}\n`;
        }
      });

      return output;
    },
  } as ToolConfig,

  batchDelete: {
    name: 'batch-delete-companies',
    handler: batchDeleteCompanies,
    formatResult: (result: any) => {
      const { results, summary } = result;
      let output = `Batch Delete Summary: ${summary.succeeded}/${summary.total} succeeded\n`;

      results.forEach((item: any) => {
        if (item.success) {
          output += `✓ Deleted: ${item.id}\n`;
        } else {
          output += `✗ Failed: ${item.id} - ${
            item.error?.message || 'Unknown error'
          }\n`;
        }
      });

      return output;
    },
  } as ToolConfig,

  batchSearch: {
    name: 'batch-search-companies',
    handler: batchSearchCompanies,
    formatResult: (result: any) => {
      const { results, summary } = result;
      let output = `Batch Search Summary: ${summary.succeeded}/${summary.total} succeeded\n\n`;

      results.forEach((item: any, index: number) => {
        if (item.success) {
          output += `Query ${index + 1}: Found ${item.data.length} companies\n`;
          item.data.forEach((company: any) => {
            output += `  - ${
              company.values?.name?.[0]?.value || 'Unknown'
            } (ID: ${company.id?.record_id})\n`;
          });
        } else {
          output += `Query ${index + 1}: Failed - ${
            item.error?.message || 'Unknown error'
          }\n`;
        }
        output += '\n';
      });

      return output;
    },
  } as ToolConfig,

  batchGetDetails: {
    name: 'batch-get-company-details',
    handler: batchGetCompanyDetails,
    formatResult: (result: any) => {
      const { results, summary } = result;
      let output = `Batch Get Details Summary: ${summary.succeeded}/${summary.total} succeeded\n\n`;

      results.forEach((item: any) => {
        if (item.success) {
          const company = item.data;
          output += `✓ ${
            company.values?.name?.[0]?.value || 'Unknown'
          } (ID: ${company.id?.record_id})\n`;
          output += `  Website: ${
            company.values?.website?.[0]?.value || 'N/A'
          }\n`;
          output += `  Industry: ${
            company.values?.industry?.[0]?.value || 'N/A'
          }\n`;
        } else {
          output += `✗ Failed: ${item.id} - ${
            item.error?.message || 'Unknown error'
          }\n`;
        }
        output += '\n';
      });

      return output;
    },
  } as ToolConfig,
};

// Batch tool definitions
export const batchToolDefinitions = [
  {
    name: 'batch-create-companies',
    description: 'Create multiple companies in a single batch operation',
    inputSchema: {
      type: 'object',
      properties: {
        companies: {
          type: 'array',
          description: 'Array of company data to create',
          items: {
            type: 'object',
            properties: {
              name: {
                type: 'string',
                description: 'Company name (required)',
              },
              website: {
                type: 'string',
                description: 'Company website URL',
              },
              description: {
                type: 'string',
                description: 'Company description',
              },
              industry: {
                type: 'string',
                description: 'Industry classification',
              },
            },
            required: ['name'],
          },
        },
        config: {
          type: 'object',
          description: 'Optional batch configuration',
          properties: {
            maxBatchSize: {
              type: 'number',
              description: 'Maximum items per batch (default: 10)',
            },
            continueOnError: {
              type: 'boolean',
              description: 'Continue processing on errors (default: true)',
            },
          },
        },
      },
      required: ['companies'],
    },
  },
  {
    name: 'batch-update-companies',
    description: 'Update multiple companies in a single batch operation',
    inputSchema: {
      type: 'object',
      properties: {
        updates: {
          type: 'array',
          description: 'Array of company updates',
          items: {
            type: 'object',
            properties: {
              id: {
                type: 'string',
                description: 'Company ID to update',
              },
              attributes: {
                type: 'object',
                description: 'Attributes to update',
              },
            },
            required: ['id', 'attributes'],
          },
        },
        config: {
          type: 'object',
          description: 'Optional batch configuration',
        },
      },
      required: ['updates'],
    },
  },
  {
    name: 'batch-delete-companies',
    description: 'Delete multiple companies in a single batch operation',
    inputSchema: {
      type: 'object',
      properties: {
        companyIds: {
          type: 'array',
          description: 'Array of company IDs to delete',
          items: {
            type: 'string',
          },
        },
        config: {
          type: 'object',
          description: 'Optional batch configuration',
        },
      },
      required: ['companyIds'],
    },
  },
  {
    name: 'batch-search-companies',
    description:
      'Perform multiple company searches in a single batch operation',
    inputSchema: {
      type: 'object',
      properties: {
        queries: {
          type: 'array',
          description: 'Array of search queries',
          items: {
            type: 'string',
          },
        },
        config: {
          type: 'object',
          description: 'Optional batch configuration',
        },
      },
      required: ['queries'],
    },
  },
  {
    name: 'batch-get-company-details',
    description:
      'Get details for multiple companies in a single batch operation',
    inputSchema: {
      type: 'object',
      properties: {
        companyIds: {
          type: 'array',
          description: 'Array of company IDs to get details for',
          items: {
            type: 'string',
          },
        },
        config: {
          type: 'object',
          description: 'Optional batch configuration',
        },
      },
      required: ['companyIds'],
    },
  },
];

/**
 * Batch operations for company records
 */
import {
  ResourceType,
  Company,
  BatchResponse,
  BatchConfig,
  RecordAttributes,
} from '../types/attio.js';
import { CompanyFieldValue } from '../types/tool-types.js';
import {
  executeBatchOperations,
  batchCreateRecords,
  batchUpdateRecords,
} from '../api/operations/index.js';
import {
  createCompany,
  updateCompany,
  deleteCompany,
  searchCompanies,
  getCompanyDetails,
} from './companies/index.js';
import { CompanyValidator } from '../validators/company-validator.js';

/**
 * Helper function to execute a batch operation with improved error handling
 *
 * This function centralizes batch operations for companies, providing consistent
 * error handling, proper object type setting, and fallback to individual operations
 * when the batch API is unavailable.
 *
 * @template T - The type of input records (e.g., RecordAttributes for create, {id, attributes} for update)
 * @template R - The type of output records (typically Company)
 * @param operationType - The type of operation (create, update, delete, etc.)
 * @param records - The records to process
 * @param batchFunction - The batch API function to call
 * @param singleFunction - The single-record fallback function
 * @param batchConfig - Optional batch configuration
 * @returns Batch response with results for each record and summary statistics
 * @throws Error if records is not an array or validation fails
 */
async function executeBatchCompanyOperation<T, R>(
  operationType: 'create' | 'update' | 'delete' | 'search' | 'get',
  records: T[],
  batchFunction: (params: any) => Promise<R[]>,
  singleFunction: (params: T) => Promise<R>,
  batchConfig?: Partial<BatchConfig>
): Promise<BatchResponse<R>> {
  // Validation check
  if (!Array.isArray(records) || records.length === 0) {
    throw new Error(
      `Invalid ${operationType} parameters: records must be a non-empty array`
    );
  }

  try {
    // Attempt to use the batch API
    const results = await batchFunction({
      objectSlug: ResourceType.COMPANIES, // Always explicitly set the resource type
      records:
        operationType === 'create'
          ? records.map((r: any) => ({ attributes: r }))
          : records,
    });

    // Format the response
    return {
      results: results.map((result, index) => ({
        id: `${operationType}_company_${index}`,
        success: true,
        data: result,
      })),
      summary: {
        total: records.length,
        succeeded: results.length,
        failed: records.length - results.length,
      },
    };
  } catch (error) {
    // Log the error for debugging
    console.error(
      `[batchCompany${
        operationType.charAt(0).toUpperCase() + operationType.slice(1)
      }] ` +
        `Batch API failed with error: ${
          error instanceof Error ? error.message : String(error)
        }`
    );

    // Fall back to individual operations
    return executeBatchOperations<T, R>(
      records.map((record, index) => ({
        id: `${operationType}_company_${index}`,
        params: record,
      })),
      singleFunction,
      batchConfig
    );
  }

